ruleToc.updateTime:
@js:(function(){
  var t = JSON.parse(String(result)).t;
  if (t === undefined || t === null || t === "") { return ""; }
  if (typeof t === "string") { return t; }
  var d = new Date(Number(t) * 1000);
  var m = d.getMonth() + 1, dd = d.getDate();
  return d.getFullYear() + "-" + (m < 10 ? "0" + m : m) + "-" + (dd < 10 ? "0" + dd : dd);
})()

