function coverOf(bookUrl) {
var m = String(bookUrl || '').match(/ciwei\/(\d+)_(\d+)\//);
if (!m) return '';
return 'http://m.ciweiku.com/files/article/image/' + m[1] + '/' + m[2] + '/' + m[2] + 's.jpg';
}
function cleanIntroText(t) {
var s = String(t || '').replace(/\s+/g, ' ').trim();
s = s.replace(/\s*\.\.\.[\s\S]*$/, '');
s = s.replace(/\[点击阅读\]/g, '').trim();
return s;
}
function mkCard(name, author, kind, last, intro, cover, bookUrl, upd) {
var div = new org.jsoup.nodes.Element('div');
var h3 = new org.jsoup.nodes.Element('h3');
var a = new org.jsoup.nodes.Element('a');
a.attr('href', bookUrl);
a.text(name || '');
h3.appendChild(a);
div.appendChild(h3);
if (cover) {
var im = new org.jsoup.nodes.Element('img');
im.attr('src', cover);
div.appendChild(im);
}
var fields = [['au', author], ['ki', kind], ['lc', last], ['ut', upd]];
for (var i = 0; i < fields.length; i++) {
var sp = new org.jsoup.nodes.Element('span');
sp.attr('class', fields[i][0]);
sp.text(fields[i][1] || '');
div.appendChild(sp);
}
var p = new org.jsoup.nodes.Element('p');
p.text(intro || '');
div.appendChild(p);
return div;
}
function mediaCards(scope) {
var out = new org.jsoup.select.Elements();
var items = scope.select('div.media, li.list-group-item');
for (var i = 0; i < items.size(); i++) {
var c = items.get(i);
if (String(c.tagName()) === 'li') {
var la = c.select('a[href*="/ciwei/"]').first();
if (!la) continue;
var lname = String(la.text()).replace(/\s+/g, ' ').trim();
var lurl = String(la.attr('abs:href') || la.attr('href') || '');
if (!lname || !lurl) continue;
out.add(mkCard(lname, '', '', '', '', coverOf(lurl), lurl, ''));
continue;
}
var a = c.select('h4.book-title a').first();
if (!a) continue;
var name = String(a.text()).replace(/\s+/g, ' ').trim();
var url = String(a.attr('abs:href') || a.attr('href') || '');
if (!name || !url) continue;
var au = c.select('.book_author a').first();
var author = au ? String(au.text()).trim() : '';
var ip = c.select('p.book-intro-index, p.cat-book-intro').first();
var intro = '';
if (ip) {
var clone = ip.clone();
clone.select('a').remove();
intro = cleanIntroText(clone.text());
}
var img = c.select('.media-left img, img').first();
var cover = img ? String(img.attr('abs:src') || img.attr('src') || '') : '';
if (!cover) cover = coverOf(url);
out.add(mkCard(name, author, '', '', intro, cover, url, ''));
}
return out;
}
function findPanel(doc, kw) {
var panels = doc.select('.panel');
for (var i = 0; i < panels.size(); i++) {
var hd = panels.get(i).select('.panel-heading').first();
if (hd && String(hd.text()).indexOf(kw) >= 0) return panels.get(i);
}
return null;
}
function tocLis(doc) {
var panels = doc.select('.panel');
for (var i = 0; i < panels.size(); i++) {
var hd = panels.get(i).select('.panel-heading').first();
if (hd && String(hd.text()).indexOf('全部章节') >= 0) return panels.get(i).select('ul.list-charts li');
}
var firstUl = doc.select('ul.list-charts').first();
return firstUl ? firstUl.select('li') : new org.jsoup.select.Elements();
}function tipItem(msg, url) {
var out = new org.jsoup.select.Elements();
var div = new org.jsoup.nodes.Element('div');
var h3 = new org.jsoup.nodes.Element('h3');
var a = new org.jsoup.nodes.Element('a');
a.attr('href', url);
a.text(msg);
h3.appendChild(a);
div.appendChild(h3);
out.add(div);
return out;
}

